  std::any parseBalance(std::any response) override {
    std::any result = ccxt::dict{
        {std::string("info"), response},
    };
    std::any codes = getObjectKeys(this->currencies);
    for (std::any i = 0; isLessThan(i, getArrayLength(codes));
         postFixIncrement(i)) {
      std::any code = ::getValue(codes, i);
      std::any currency = this->currency(code);
      std::any currencyId = ::getValue(currency, std::string("id"));
      if (isTrue(inOp(response, currencyId))) {
        std::any account = this->account();
        std::any reserved = add(currencyId, std::string("_reserved"));
        ::setValue(account, std::string("free"),
                   this->safeString(response, currencyId));
        ::setValue(account, std::string("used"),
                   this->safeString(response, reserved));
        ::setValue(result, code, account);
      }
    }
    return this->safeBalance(result);
  }

  /**
   * @method
   * @name coincheck#fetchStatus
   * @description the latest known information on the availability of the
   * exchange API
   * @see https://coincheck.com/documents/exchange/api#status-retrieval
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} a [status structure]{@link
   * https://docs.ccxt.com/?id=exchange-status-structure}
   */
  std::shared_future<std::any>
  fetchStatus(std::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 std::any response =
                     awaitValue(this->publicGetExchangeStatus(params));
                 //
                 //     {
                 //         "exchange_status": [
                 //             {
                 //                 "pair": "btc_jpy",
                 //                 "status": "available",
                 //                 "timestamp": 1782787596,
                 //                 "availability": {
                 //                     "order": true,
                 //                     "market_order": true,
                 //                     "cancel": true
                 //                 }
                 //             }
                 //         ]
                 //     }
                 //
                 std::any exchangeStatuses = this->safeList(
                     response, std::string("exchange_status"), ccxt::list{});
                 std::any status = std::string("ok");
                 std::any updated = std::any{};
                 for (std::any i = 0;
                      isLessThan(i, getArrayLength(exchangeStatuses));
                      postFixIncrement(i)) {
                   std::any exchangeStatus = ::getValue(exchangeStatuses, i);
                   std::any rawStatus =
                       this->safeString(exchangeStatus, std::string("status"));
                   if (isTrue(isEqual(updated, std::any{}))) {
                     updated = this->safeTimestamp(exchangeStatus,
                                                   std::string("timestamp"));
                   }
                   if (isTrue(!isEqual(rawStatus, std::string("available")))) {
                     status = std::string("maintenance");
                   }
                 }
                 return ccxt::dict{
                     {std::string("status"), status},
                     {std::string("updated"), updated},
                     {std::string("eta"), std::any{}},
                     {std::string("url"), std::any{}},
                     {std::string("info"), response},
                 };
               })
        .share();
  }

  /**
   * @method
   * @name coincheck#fetchBalance
   * @description query for balance and get the amount of funds available for
   * trading or funds locked in orders
   * @see
   * https://coincheck.com/documents/exchange/api#order-transactions-pagination
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} a [balance structure]{@link
   * https://docs.ccxt.com/?id=balance-structure}
   */
  std::shared_future<std::any>
  fetchBalance(std::any params = ccxt::dict{}) override {
    return std::async(std::launch::deferred,
                      [=]() mutable -> std::any {
                        if (isTrue(isEqual(this->markets, std::any{}))) {
                          awaitValue(this->loadMarkets());
                        }
                        std::any response =
                            awaitValue(this->privateGetAccountsBalance(params));
                        return this->parseBalance(response);
                      })
        .share();
  }

  /**
   * @method
   * @name coincheck#fetchOpenOrders
   * @description fetch all unfilled currently open orders
   * @see https://coincheck.com/documents/exchange/api#order-opens
   * @param {string} symbol unified market symbol
   * @param {int} [since] the earliest time in ms to fetch open orders for
   * @param {int} [limit] the maximum number of  open orders structures to
   * retrieve
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {Order[]} a list of [order structures]{@link
   * https://docs.ccxt.com/?id=order-structure}
   */
  std::shared_future<std::any>
  fetchOpenOrders(std::any symbol = std::any{}, std::any since = std::any{},
                  std::any limit = std::any{},
                  std::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 if (isTrue(isEqual(this->markets, std::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 // Only BTC/JPY is meaningful
                 std::any market = std::any{};
                 if (isTrue(!isEqual(symbol, std::any{}))) {
                   market = this->market(symbol);
                 }
                 std::any response =
                     awaitValue(this->privateGetExchangeOrdersOpens(params));
                 std::any rawOrders = this->safeValue(
                     response, std::string("orders"), ccxt::list{});
                 std::any parsedOrders =
                     this->parseOrders(rawOrders, market, since, limit);
                 std::any result = ccxt::list{};
                 for (std::any i = 0;
                      isLessThan(i, getArrayLength(parsedOrders));
                      postFixIncrement(i)) {
                   arrayPush(result, this->extend(::getValue(parsedOrders, i),
                                                  ccxt::dict{
                                                      {std::string("status"),
                                                       std::string("open")},
                                                  }));
                 }
                 return result;
               })
        .share();
  }

  std::any parseOrder(std::any order, std::any market = std::any{}) override {
    //
    // fetchOpenOrders
    //
    //     {                        id:  202835,
    //                      "order_type": "buy",
    //                            "rate":  26890,
    //                            "pair": "btc_jpy",
    //                  "pending_amount": "0.5527",
    //       "pending_market_buy_amount":  null,
    //                  "stop_loss_rate":  null,
    //                      "created_at": "2015-01-10T05:55:38.000Z" }
    //
    // todo: add formats for fetchOrder, fetchClosedOrders here
    //
    std::any id = this->safeString(order, std::string("id"));
    std::any side = this->safeString(order, std::string("order_type"));
    std::any timestamp =
        this->parse8601(this->safeString(order, std::string("created_at")));
    std::any amount = this->safeString(order, std::string("pending_amount"));
    std::any remaining = this->safeString(order, std::string("pending_amount"));
    std::any price = this->safeString(order, std::string("rate"));
    std::any status = std::any{};
    std::any marketId = this->safeString(order, std::string("pair"));
    std::any symbol = this->safeSymbol(marketId, market, std::string("_"));
    return this->safeOrder(
        ccxt::dict{
            {std::string("id"), id},
            {std::string("clientOrderId"), std::any{}},
            {std::string("timestamp"), timestamp},
            {std::string("datetime"), this->iso8601(timestamp)},
            {std::string("lastTradeTimestamp"), std::any{}},
            {std::string("amount"), amount},
            {std::string("remaining"), remaining},
            {std::string("filled"), std::any{}},
            {std::string("side"), side},
            {std::string("type"), std::any{}},
            {std::string("timeInForce"), std::any{}},
            {std::string("postOnly"), std::any{}},
            {std::string("status"), status},
            {std::string("symbol"), symbol},
            {std::string("price"), price},
            {std::string("triggerPrice"), std::any{}},
            {std::string("cost"), std::any{}},
            {std::string("fee"), std::any{}},
            {std::string("info"), order},
            {std::string("average"), std::any{}},
            {std::string("trades"), std::any{}},
        },
        market);
  }

  /**
   * @method
   * @name coincheck#fetchOrderBook
   * @description fetches information on open orders with bid (buy) and ask
   * (sell) prices, volumes and other data
   * @see https://coincheck.com/documents/exchange/api#order-book
   * @param {string} symbol unified symbol of the market to fetch the order book
   * for
   * @param {int} [limit] the maximum amount of order book entries to return
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} an [order book structure]{@link
   * https://docs.ccxt.com/?id=order-book-structure}
   */
  std::shared_future<std::any>
  fetchOrderBook(std::any symbol, std::any limit = std::any{},
                 std::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 if (isTrue(isEqual(this->markets, std::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 std::any market = this->market(symbol);
                 std::any request = ccxt::dict{
                     {std::string("pair"),
                      ::getValue(market, std::string("id"))},
                 };
                 std::any response = awaitValue(
                     this->publicGetOrderBooks(this->extend(request, params)));
                 return this->parseOrderBook(
                     response, ::getValue(market, std::string("symbol")));
               })
        .share();
  }

  std::any parseTicker(std::any ticker, std::any market = std::any{}) override {
    //
    // {
    //     "last":4192632.0,
    //     "bid":4192496.0,
    //     "ask":4193749.0,
    //     "high":4332000.0,
    //     "low":4101047.0,
    //     "volume":2313.43191762,
    //     "timestamp":1643374115
    // }
    //
    std::any symbol = this->safeSymbol(std::any{}, market);
    std::any timestamp = this->safeTimestamp(ticker, std::string("timestamp"));
    std::any last = this->safeString(ticker, std::string("last"));
    return this->safeTicker(
        ccxt::dict{
            {std::string("symbol"), symbol},
            {std::string("timestamp"), timestamp},
            {std::string("datetime"), this->iso8601(timestamp)},
            {std::string("high"),
             this->safeString(ticker, std::string("high"))},
            {std::string("low"), this->safeString(ticker, std::string("low"))},
            {std::string("bid"), this->safeString(ticker, std::string("bid"))},
            {std::string("bidVolume"), std::any{}},
            {std::string("ask"), this->safeString(ticker, std::string("ask"))},
            {std::string("askVolume"), std::any{}},
            {std::string("vwap"), std::any{}},
            {std::string("open"), std::any{}},
            {std::string("close"), last},
            {std::string("last"), last},
            {std::string("previousClose"), std::any{}},
            {std::string("change"), std::any{}},
            {std::string("percentage"), std::any{}},
            {std::string("average"), std::any{}},
            {std::string("baseVolume"),
             this->safeString(ticker, std::string("volume"))},
            {std::string("quoteVolume"), std::any{}},
            {std::string("info"), ticker},
        },
        market);
  }

  /**
   * @method
   * @name coincheck#fetchTicker
   * @description fetches a price ticker, a statistical calculation with the
   * information calculated over the past 24 hours for a specific market
   * @see https://coincheck.com/documents/exchange/api#ticker
   * @param {string} symbol unified symbol of the market to fetch the ticker for
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} a [ticker structure]{@link
   * https://docs.ccxt.com/?id=ticker-structure}
   */
  std::shared_future<std::any>
  fetchTicker(std::any symbol, std::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 if (isTrue(!isEqual(symbol, std::string("BTC/JPY")))) {
                   throw BadSymbol(toString(add(
                       this->id,
                       std::string(" fetchTicker() supports BTC/JPY only"))));
                 }
                 if (isTrue(isEqual(this->markets, std::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 std::any market = this->market(symbol);
                 std::any request = ccxt::dict{
                     {std::string("pair"),
                      ::getValue(market, std::string("id"))},
                 };
                 std::any ticker = awaitValue(
                     this->publicGetTicker(this->extend(request, params)));
                 //
                 // {
                 //     "last":4192632.0,
                 //     "bid":4192496.0,
                 //     "ask":4193749.0,
                 //     "high":4332000.0,
                 //     "low":4101047.0,
                 //     "volume":2313.43191762,
                 //     "timestamp":1643374115
                 // }
                 //
                 return this->parseTicker(ticker, market);
               })
        .share();
  }

  std::any parseTrade(std::any trade, std::any market = std::any{}) override {
    //
    // fetchTrades (public)
    //
    //      {
    //          "id": "206849494",
    //          "amount": "0.01",
    //          "rate": "5598346.0",
    //          "pair": "btc_jpy",
    //          "order_type": "sell",
    //          "created_at": "2021-12-08T14:10:33.000Z"
    //      }
    //
    // fetchMyTrades (private) - example from docs
    //
    //      {
    //          "id": 38,
    //          "order_id": 49,
    //          "created_at": "2015-11-18T07:02:21.000Z",
    //          "funds": {
    //              "btc": "0.1",
    //              "jpy": "-4096.135"
    //                  },
    //           "pair": "btc_jpy",
    //           "rate": "40900.0",
    //           "fee_currency": "JPY",
    //           "fee": "6.135",
    //           "liquidity": "T",
    //           "side": "buy"
    //      }
    //
    std::any timestamp =
        this->parse8601(this->safeString(trade, std::string("created_at")));
    std::any id = this->safeString(trade, std::string("id"));
    std::any priceString = this->safeString(trade, std::string("rate"));
    std::any marketId = this->safeString(trade, std::string("pair"));
    market = this->safeMarket(marketId, market, std::string("_"));
    std::any baseId = ::getValue(market, std::string("baseId"));
    std::any quoteId = ::getValue(market, std::string("quoteId"));
    std::any symbol = ::getValue(market, std::string("symbol"));
    std::any takerOrMaker = std::any{};
    std::any amountString = std::any{};
    std::any costString = std::any{};
    std::any side = std::any{};
    std::any fee = std::any{};
    std::any orderId = std::any{};
    if (isTrue(inOp(trade, std::string("liquidity")))) {
      if (isTrue(isEqual(this->safeString(trade, std::string("liquidity")),
                         std::string("T")))) {
        takerOrMaker = std::string("taker");
      } else if (isTrue(
                     isEqual(this->safeString(trade, std::string("liquidity")),
                             std::string("M")))) {
        takerOrMaker = std::string("maker");
      }
      std::any funds =
          this->safeValue(trade, std::string("funds"), ccxt::dict{});
      amountString = this->safeString(funds, baseId);
      costString = this->safeString(funds, quoteId);
      fee = ccxt::dict{
          {std::string("currency"),
           this->safeString(trade, std::string("fee_currency"))},
          {std::string("cost"), this->safeString(trade, std::string("fee"))},
      };
      side = this->safeString(trade, std::string("side"));
      orderId = this->safeString(trade, std::string("order_id"));
    } else {
      amountString = this->safeString(trade, std::string("amount"));
      side = this->safeString(trade, std::string("order_type"));
    }
    return this->safeTrade(
        ccxt::dict{
            {std::string("id"), id},
            {std::string("info"), trade},
            {std::string("datetime"), this->iso8601(timestamp)},
            {std::string("timestamp"), timestamp},
            {std::string("symbol"), symbol},
            {std::string("type"), std::any{}},
            {std::string("side"), side},
            {std::string("order"), orderId},
            {std::string("takerOrMaker"), takerOrMaker},
            {std::string("price"), priceString},
            {std::string("amount"), amountString},
            {std::string("cost"), costString},
            {std::string("fee"), fee},
        },
        market);
  }

  /**
   * @method
   * @name coincheck#fetchMyTrades
   * @description fetch all trades made by the user
   * @see
   * https://coincheck.com/documents/exchange/api#order-transactions-pagination
   * @param {string} symbol unified market symbol
   * @param {int} [since] the earliest time in ms to fetch trades for
   * @param {int} [limit] the maximum number of trades structures to retrieve
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {Trade[]} a list of [trade structures]{@link
   * https://docs.ccxt.com/?id=trade-structure}
   */
  std::shared_future<std::any>
  fetchMyTrades(std::any symbol = std::any{}, std::any since = std::any{},
                std::any limit = std::any{},
                std::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 if (isTrue(isEqual(this->markets, std::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 std::any market = this->market(symbol);
                 std::any request = ccxt::dict{};
                 if (isTrue(!isEqual(limit, std::any{}))) {
                   ::setValue(request, std::string("limit"), limit);
                 }
                 std::any response = awaitValue(
                     this->privateGetExchangeOrdersTransactionsPagination(
                         this->extend(request, params)));
                 //
                 //      {
                 //          "success": true,
                 //          "data": [
                 //                      {
                 //                          "id": 38,
                 //                          "order_id": 49,
                 //                          "created_at":
                 //                          "2015-11-18T07:02:21.000Z",
                 //                          "funds": {
                 //                              "btc": "0.1",
                 //                              "jpy": "-4096.135"
                 //                                  },
                 //                          "pair": "btc_jpy",
                 //                          "rate": "40900.0",
                 //                          "fee_currency": "JPY",
                 //                          "fee": "6.135",
                 //                          "liquidity": "T",
                 //                          "side": "buy"
                 //                       },
                 //                  ]
                 //      }
                 //
                 std::any transactions = this->safeList(
                     response, std::string("data"), ccxt::list{});
                 return this->parseTrades(transactions, market, since, limit);
               })
        .share();
  }

