  virtual std::any parseTransactionStatus(std::any status) {
    std::any statuses = ccxt::dict{
        {std::string("pending"), std::string("pending")},
        {std::string("processing"), std::string("pending")},
        {std::string("finished"), std::string("ok")},
        {std::string("canceled"), std::string("canceled")},
        {std::string("confirmed"), std::string("pending")},
        {std::string("received"), std::string("ok")},
    };
    return this->safeString(statuses, status, status);
  }

  std::any parseTransaction(std::any transaction,
                            std::any currency = std::any{},
                            std::any p2 = std::any{},
                            std::any p3 = std::any{}) override {
    //
    // fetchDeposits
    //
    // {
    //       "id": 2,
    //       "amount": "0.05",
    //       "currency": "BTC",
    //       "address": "13PhzoK8me3u5nHzzFD85qT9RqEWR9M4Ty",
    //       "status": "confirmed",
    //       "confirmed_at": "2015-06-13T08:29:18.000Z",
    //       "created_at": "2015-06-13T08:22:18.000Z"
    //  }
    //
    // fetchWithdrawals
    //
    //  {
    //       "id": 398,
    //       "status": "finished",
    //       "amount": "242742.0",
    //       "currency": "JPY",
    //       "created_at": "2014-12-04T15:00:00.000Z",
    //       "bank_account_id": 243,
    //       "fee": "400.0",
    //       "is_fast": true
    //  }
    //
    std::any id = this->safeString(transaction, std::string("id"));
    std::any timestamp = this->parse8601(
        this->safeString(transaction, std::string("created_at")));
    std::any address = this->safeString(transaction, std::string("address"));
    std::any amount = this->safeNumber(transaction, std::string("amount"));
    std::any currencyId =
        this->safeString(transaction, std::string("currency"));
    std::any code = this->safeCurrencyCode(currencyId, currency);
    std::any status = this->parseTransactionStatus(
        this->safeString(transaction, std::string("status")));
    std::any updated = this->parse8601(
        this->safeString(transaction, std::string("confirmed_at")));
    std::any fee = std::any{};
    std::any feeCost = this->safeNumber(transaction, std::string("fee"));
    if (isTrue(!isEqual(feeCost, std::any{}))) {
      fee = ccxt::dict{
          {std::string("cost"), feeCost},
          {std::string("currency"), code},
      };
    }
    return ccxt::dict{
        {std::string("info"), transaction},
        {std::string("id"), id},
        {std::string("txid"), std::any{}},
        {std::string("timestamp"), timestamp},
        {std::string("datetime"), this->iso8601(timestamp)},
        {std::string("network"), std::any{}},
        {std::string("address"), address},
        {std::string("addressTo"), address},
        {std::string("addressFrom"), std::any{}},
        {std::string("tag"), std::any{}},
        {std::string("tagTo"), std::any{}},
        {std::string("tagFrom"), std::any{}},
        {std::string("type"), std::any{}},
        {std::string("amount"), amount},
        {std::string("currency"), code},
        {std::string("status"), status},
        {std::string("updated"), updated},
        {std::string("comment"), std::any{}},
        {std::string("internal"), std::any{}},
        {std::string("fee"), fee},
    };
  }

  std::any nonce() override { return this->milliseconds(); }

  std::any sign(std::any path, std::any api = std::string("public"),
                std::any method = std::string("GET"),
                std::any params = ccxt::dict{}, std::any headers = std::any{},
                std::any body = std::any{}) override {
    std::any url =
        add(add(::getValue(::getValue(this->urls, std::string("api")),
                           std::string("rest")),
                std::string("/")),
            this->implodeParams(path, params));
    std::any query = this->omit(params, this->extractParams(path));
    if (isTrue(isEqual(api, std::string("public")))) {
      if (isTrue(isGreaterThan(getArrayLength(getObjectKeys(query)), 0))) {
        url = add(url, add(std::string("?"), this->urlencode(query)));
      }
    } else {
      this->checkRequiredCredentials();
      std::any nonce = toString(this->nonce());
      std::any queryString = std::string("");
      if (isTrue(isEqual(method, std::string("GET")))) {
        if (isTrue(isGreaterThan(getArrayLength(getObjectKeys(query)), 0))) {
          url = add(url, add(std::string("?"),
                             this->urlencode(this->keysort(query))));
        }
      } else {
        if (isTrue(isGreaterThan(getArrayLength(getObjectKeys(query)), 0))) {
          body = this->urlencode(this->keysort(query));
          queryString = body;
        }
      }
      std::any auth = add(add(nonce, url), queryString);
      headers = ccxt::dict{
          {std::string("Content-Type"),
           std::string("application/x-www-form-urlencoded")},
          {std::string("ACCESS-KEY"), this->apiKey},
          {std::string("ACCESS-NONCE"), nonce},
          {std::string("ACCESS-SIGNATURE"),
           this->hmac(this->encode(auth), this->encode(this->secret), sha256)},
      };
    }
    return ccxt::dict{
        {std::string("url"), url},
        {std::string("method"), method},
        {std::string("body"), body},
        {std::string("headers"), headers},
    };
  }

  std::any handleErrors(std::any httpCode, std::any reason, std::any url,
                        std::any method, std::any headers, std::any body,
                        std::any response, std::any requestHeaders,
                        std::any requestBody) override {
    if (isTrue(isEqual(response, std::any{}))) {
      return std::any{};
    }
    //
    //     {"success":false,"error":"disabled API Key"}'
    //     {"success":false,"error":"invalid authentication"}
    //
    std::any success = this->safeBool(response, std::string("success"), true);
    if (isTrue(!isEqual(success, true))) {
      std::any error = this->safeString(response, std::string("error"));
      std::any feedback =
          add(add(this->id, std::string(" ")), this->json(response));
      this->throwExactlyMatchedException(
          ::getValue(this->exceptions, std::string("exact")), error, feedback);
      this->throwBroadlyMatchedException(
          ::getValue(this->exceptions, std::string("broad")), body, feedback);
      throw ExchangeError(
          toString(add(add(this->id, std::string(" ")), this->json(response))));
    }
    return std::any{};
  }
